            //OK            //Offset the coordinate system so that point (0, 0) is at thecenter of the desired area.            g.TranslateTransform(rect.Left + Width / 2, rect.Top + Height / 2);            // Rotate the Graphics object.            g.RotateTransform(Rotation);            SizeF textSize = g.MeasureString(Text, Font);            g.DrawString(Text, Font, Brushes.Red, -(textSize.Width / 2), -(textSize.Height / 2));            //Reset the graphics object Transformations.            g.ResetTransform();